import {chartQuestions,patternTopics,patternCards} from './chart-content.js?v=382f06ff093b';
import {dayLessons,glossary} from './daytrade-content.js?v=382f06ff093b';
import {shuffle,grade,topicStats} from './training-engine.js?v=382f06ff093b';
import {candles,chartTable} from './training-charts.js?v=382f06ff093b';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let ctx;
const source=s=>`${esc(s.pdf||s.file)} · PDF page ${s.pdfPage||s.pages?.join(', ')}${s.slide?' · slide '+esc(s.slide):''}${s.chapter?' · '+esc(s.chapter):''}${s.printed?' · printed '+esc(s.printed):''}`;
const tabs=active=>`<div class="training-tabs" role="navigation" aria-label="Learning tracks"><a class="${active==='options'?'active':''}" href="#Guided%20Lessons/options">Options curriculum</a><a class="${active==='day'?'active':''}" href="#Guided%20Lessons/day">Ross Cameron study track</a><a class="${active==='patterns'?'active':''}" href="#Guided%20Lessons/patterns">Pattern references</a><a class="${active==='glossary'?'active':''}" href="#Guided%20Lessons/glossary">Search glossary</a></div>`;
function save(){ctx.persist(false)}
function navigate(hash){if(location.hash===hash)ctx.render();else location.hash=hash}
function chartBlock(f,reveal=false,region=false){return `<figure><figcaption>Synthetic illustration · fictional stock prices and volume · ${esc(f.timeframe)} per candle</figcaption><div class="chart-frame">${candles(f,{reveal,region})}</div><button type="button" data-expand>Expand chart</button>${chartTable(f)}</figure>`}
function bindChart(f,reveal=false,region=false){document.querySelectorAll('[data-expand]').forEach(b=>b.onclick=()=>{ctx.modal(`<h2>Expanded synthetic chart</h2><p>Fictional illustration, not historical data. ${f.timeframe} per bar.</p><div class="chart-frame zoom">${candles(f,{reveal,region:false})}</div>${chartTable(f)}`)})}
function feedback(q,a){return `<section class="answer-feedback" role="status"><h3>${a.correct?'Correct analysis':'Review this analysis'}${a.hinted?' · hinted attempt':''}</h3><p>${esc(q.explanation)}</p>${q.type==='numeric'?`<p>Accepted answer: ${q.answer} ± ${q.tolerance}. ${esc(q.interpretation)}</p>`:`<ul>${q.options.map(o=>`<li><strong>${o.id===q.correct?'Correct: ':''}${esc(o.text)}</strong> — ${esc(o.explanation)}</li>`).join('')}</ul>`}<p class="source">${source(q.source)}</p><p>${esc(q.interpretation)}</p><a href="#Guided%20Lessons/pattern/${q.topic}">Review the explanation</a><p class="muted">This is a defensible answer to the stated analysis, not a promise about future prices or a real-money recommendation.</p></section>`}
export function renderChallenges(context){ctx=context;const l=ctx.state.learning,stats=topicStats(chartQuestions,l.attempts.filter(a=>a.revealed!==false)),missed=[...stats.latest.values()].filter(a=>!a.correct),seen=stats.first.length,firstCorrect=stats.first.filter(a=>a.correct).length,everWrong=new Set(l.attempts.filter(a=>!a.correct).map(a=>a.questionId)),resolved=[...everWrong].filter(id=>stats.latest.get(id)?.correct).length,filter=decodeURIComponent(location.hash).split('/')[2]||'';$('#page').innerHTML=`<div class="training"><div class="eyebrow">Read the chart. Explain your decision.</div><h1>Chart Pattern Challenges</h1><p>Original illustrations inspired by the chart guide. Stock chart analysis stays separate from options trading.</p><div class="grid stats"><div class="card"><small>First-attempt accuracy</small><h2>${seen?Math.round(firstCorrect/seen*100):0}%</h2><p>${firstCorrect} correct / ${seen} first attempts</p></div><div class="card"><small>Hinted attempts</small><h2>${l.attempts.filter(a=>a.hinted).length}</h2><p>Reported separately from unhinted work</p></div><div class="card"><small>Missed questions</small><h2>${missed.length}</h2><p>Latest response still needs review</p></div><div class="card"><small>Review progress</small><h2>${resolved} / ${everWrong.size}</h2><p>Previously missed questions corrected</p></div></div><section class="card"><div class="fields two"><label>Practice mode<select id="practiceMode"><option value="quick">Quick Practice · 10 questions</option><option value="topic">By Topic · up to 10 questions</option><option value="mixed">Mixed Quiz · 20 questions</option><option value="review">Review Mistakes</option></select></label><label>Topic<select id="practiceTopic">${patternTopics.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select></label></div><button class="primary" id="startSession">Start new session</button><p>Quick Practice gives immediate feedback. Mixed Quiz reveals scores and explanations after submission. No question repeats within a session.</p><p class="source">${ctx.state.challenges.length} legacy options-challenge completions preserved. They do not count as chart-question completions.</p></section><div id="session" class="section-gap"></div><details class="card section-gap"><summary>Accuracy by topic and missed-question list</summary><div class="table-wrap"><table><thead><tr><th>Topic</th><th>First-attempt correct</th></tr></thead><tbody>${patternTopics.map(t=>`<tr><td>${esc(t.title)}</td><td>${stats.byTopic[t.id].correct} / ${stats.byTopic[t.id].seen}</td></tr>`).join('')}</tbody></table></div>${missed.map(a=>{const q=chartQuestions.find(q=>q.id===a.questionId);return q?`<p>${esc(q.prompt)} <a href="#Guided%20Lessons/pattern/${q.topic}">Review the explanation</a></p>`:''}).join('')}</details></div>`;
if(l.session){$('#practiceMode').value=l.session.mode;if(l.session.topic)$('#practiceTopic').value=l.session.topic}if(filter&&patternTopics.some(t=>t.id===filter)){$('#practiceMode').value='topic';$('#practiceTopic').value=filter}$('#practiceTopic').disabled=$('#practiceMode').value!=='topic';$('#practiceMode').onchange=()=>$('#practiceTopic').disabled=$('#practiceMode').value!=='topic';$('#startSession').onclick=()=>{if(l.session&&!l.session.submitted&&l.session.index<l.session.ids.length&&!confirm('Leave the unfinished session? Recorded attempts remain saved.'))return;let pool=chartQuestions,mode=$('#practiceMode').value;if(mode==='topic')pool=pool.filter(q=>q.topic===$('#practiceTopic').value);if(mode==='review')pool=pool.filter(q=>missed.some(a=>a.questionId===q.id));if(!pool.length){ctx.toast('No missed questions to review yet.');return}const seed=crypto.getRandomValues(new Uint32Array(1))[0],ids=shuffle(pool.map(q=>q.id),seed).slice(0,mode==='mixed'?20:10);l.session={id:crypto.randomUUID(),mode,topic:mode==='topic'?$('#practiceTopic').value:null,seed,ids,index:0,answers:{},hinted:{},submitted:false};save();sessionView()};sessionView()}
function sessionView(){const s=ctx.state.learning.session;if(!s){$('#session').innerHTML='<section class="card"><h2>Start with observation.</h2><p>Look for the price sequence, a reference level and a condition that would weaken your reading. No practice-account money is affected.</p></section>';return}if(s.index>=s.ids.length){summary(s);return}const q=chartQuestions.find(q=>q.id===s.ids[s.index]);if(!q){$('#session').innerHTML='<p>That saved question is unavailable. Start a new session; your recorded attempts remain preserved.</p>';return}const a=s.answers[q.id],reveal=!!a&&(s.mode!=='mixed'||s.submitted),order=shuffle(q.options||[],s.seed+s.index*31);$('#session').innerHTML=`<section class="card"><div class="split"><span>Question ${s.index+1} of ${s.ids.length} · ${q.difficulty}</span><span>${s.mode==='mixed'?'Mixed Quiz':`Session score ${Object.values(s.answers).filter(a=>a.correct).length} / ${Object.keys(s.answers).length}`}</span></div><progress max="${s.ids.length}" value="${Object.keys(s.answers).length}" aria-label="Session questions answered"></progress><h2>${esc(q.prompt)}</h2><p>${esc(q.assumptions)}</p>${q.chart?chartBlock(q.chart,reveal,q.type==='region'):''}<form id="answerForm">${q.type==='numeric'?`<label>Numerical answer<input id="numericAnswer" type="number" step="any" required ${a?'disabled':''} value="${a?esc(a.answer):''}"></label><p class="source">Tolerance: ±${q.tolerance}; zero means an exact whole-number answer.</p>`:`<fieldset ${a?'disabled':''}><legend>${q.type==='region'?'Choose a chart region (click, touch, or keyboard selection below)':'Choose the most defensible answer'}</legend>${order.map(o=>`<label class="answer-option"><input type="radio" name="answer" value="${o.id}" required ${a?.answer===o.id?'checked':''}>${esc(o.text)}</label>`).join('')}</fieldset>`}<div class="row section-gap">${!a?'<button class="primary" type="submit">Record answer</button><button id="showHint" type="button">Show hint · marks hinted attempt</button>':''}${a?`<button id="nextQuestion" class="primary" type="button">${s.index===s.ids.length-1?(s.mode==='mixed'?'Review and submit quiz':'Finish session'):'Next question'}</button>`:''}${s.index>0?'<button id="previousQuestion" type="button">Previous question</button>':''}</div></form>${s.hinted[q.id]?`<p class="notice">Hint: ${esc(q.hint)}</p>`:''}${reveal?feedback(q,a):a?'<p class="notice">Answer recorded. Score and explanations remain hidden until you submit the quiz.</p>':''}</section>`;
if(q.chart)bindChart(q.chart,reveal,q.type==='region');document.querySelectorAll('[data-region]').forEach(b=>{const pick=()=>{if(a)return;const radio=document.querySelector(`input[name="answer"][value="${b.dataset.region}"]`);if(radio){radio.checked=true;radio.focus()}};b.onclick=pick;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick()}}});$('#answerForm').onsubmit=e=>{e.preventDefault();if(s.answers[q.id])return;const value=q.type==='numeric'?Number($('#numericAnswer').value):document.querySelector('input[name="answer"]:checked')?.value;if(value===undefined||q.type==='numeric'&&(!Number.isFinite(value)||$('#numericAnswer').value===''))return;const attempt={id:s.id+':'+q.id,sessionId:s.id,questionId:q.id,answer:value,correct:grade(q,value),revealed:s.mode!=='mixed',hinted:!!s.hinted[q.id],at:new Date().toISOString()};s.answers[q.id]=attempt;ctx.state.learning.attempts.push(attempt);save();renderChallenges(ctx)};if($('#showHint'))$('#showHint').onclick=()=>{s.hinted[q.id]=true;save();sessionView()};if($('#nextQuestion'))$('#nextQuestion').onclick=()=>{s.index++;save();sessionView()};if($('#previousQuestion'))$('#previousQuestion').onclick=()=>{s.index--;save();sessionView()}}
function summary(s){if(s.mode==='mixed'&&!s.submitted){$('#session').innerHTML=`<section class="card"><h2>Ready to submit?</h2><p>${Object.keys(s.answers).length} of ${s.ids.length} answers recorded. No explanations have been revealed.</p><button id="submitQuiz" class="primary">Submit quiz</button><button id="backQuiz">Review answers</button></section>`;$('#submitQuiz').onclick=()=>{s.submitted=true;for(const a of ctx.state.learning.attempts)if(a.sessionId===s.id)a.revealed=true;save();renderChallenges(ctx)};$('#backQuiz').onclick=()=>{s.index=0;save();sessionView()};return}s.submitted=true;save();const answers=Object.values(s.answers),correct=answers.filter(a=>a.correct).length;$('#session').innerHTML=`<section class="card"><h2>Session complete · ${correct} / ${s.ids.length}</h2><p>${answers.filter(a=>a.hinted).length} hinted attempts. This checks analysis under stated assumptions; passing is not evidence of readiness for profitable real-money trading.</p>${s.ids.map((id,i)=>{const q=chartQuestions.find(q=>q.id===id),a=s.answers[id];return q?`<details><summary>${a?.correct?'Correct':'Review'} · ${esc(q.prompt)}</summary>${q.chart?candles(q.chart,{reveal:true}):''}${feedback(q,a)}</details>`:''}).join('')}</section>`}
export function renderLearning(context){ctx=context;const parts=decodeURIComponent(location.hash).split('/'),track=parts[1]||'',id=parts[2];if(track==='options'){ctx.optionsLearning();$('#page').insertAdjacentHTML('afterbegin',`<div class="training">${tabs('options')}</div>`);return}if(track==='day'&&id){showDayLesson(id);return}if(track==='pattern'&&id){showPattern(id);return}if(track==='patterns'){$('#page').innerHTML=`<div class="training">${tabs('patterns')}<h1>Chart-guide reference cards</h1><p>Supplemental concepts from ChartPatternsv2.pdf, separate from the Ross Cameron book track. All price illustrations are synthetic.</p><div class="grid lesson-grid">${patternCards.map(c=>`<article class="card"><h2>${esc(c.title)}</h2><p>${esc(c.explanation)}</p><p class="source">${source(c.source)}</p><a href="#Guided%20Lessons/pattern/${c.topic}">Read reference and practice</a></article>`).join('')}</div></div>`;return}if(track==='glossary'){glossaryView();return}const l=ctx.state.learning;$('#page').innerHTML=`<div class="training">${tabs(track==='day'?'day':'')}<div class="eyebrow">Separate paths. Shared curiosity.</div><h1>${track==='day'?'How to Day Trade — Ross Cameron Study Track':'Guided lessons'}</h1><p>This study track primarily concerns stock day trading. It does not convert stock setups into options recommendations. Learning checks are practice, not proof of profitable real-money readiness.</p><div class="grid learning-progress"><a href="#Guided%20Lessons/options" class="card"><strong>Options curriculum</strong><p>${ctx.state.completed.length} / 14 lessons completed</p></a><a href="#Guided%20Lessons/day" class="card"><strong>Stock day-trading study</strong><p>${l.dayCompleted.length} / ${dayLessons.length} lessons completed</p></a><a href="#Challenges" class="card"><strong>Chart Pattern Challenges</strong><p>${new Set(l.attempts.map(a=>a.questionId)).size} / ${chartQuestions.length} questions attempted</p></a></div><p class="notice">Original explanations and worked examples based on your supplied book. Historical personal results are not typical outcomes or promises. Source page references use physical PDF positions and printed pages separately.</p><div class="grid lesson-grid">${dayLessons.map((l,i)=>`<article class="card lesson-card"><span class="pill">${ctx.state.learning.dayCompleted.includes(l.id)?'Completed':'Not completed'} · ${esc(l.minutes)} minutes</span><h2>${esc(l.title)}</h2><p>${esc(l.objective)}</p><p class="source">${source(l.source)}</p><a class="study-link" href="#Guided%20Lessons/day/${l.id}">Study lesson</a></article>`).join('')}</div></div>`}
function showDayLesson(id){const i=dayLessons.findIndex(l=>l.id===id);if(i<0){navigate('#Guided%20Lessons/day');return}const l=dayLessons[i],progress=ctx.state.learning.dayProgress[id]||{exerciseCorrect:false,checkAnswers:{}},practice=patternTopics.some(t=>t.id===l.practiceTopic)?l.practiceTopic:['headline','headline','first-pullback','ipo','micro','bull-flag','five-minute','one-minute','premarket-quality','abcd-stall','first-pullback','bull-trap'][i];const ready=()=>progress.exerciseCorrect&&l.checks.every(q=>progress.checkAnswers[q.id]===q.answer);const diagram=l.diagram?.kind==='candle'?candleDiagram(l.diagram):l.diagram?.kind==='risk'?riskDiagram(l.diagram):'';$('#page').innerHTML=`<div class="training">${tabs('day')}<p><a href="#Guided%20Lessons/day">All study lessons</a></p><article class="card study-article"><div class="eyebrow">Stock day trading · ${esc(l.minutes)} minutes</div><h1>${esc(l.title)}</h1><p><strong>Learning objective:</strong> ${esc(l.objective)}</p><p class="source">${source(l.source)}</p><h2>Understand the idea</h2>${(Array.isArray(l.explanation)?l.explanation:[l.explanation]).map(p=>`<p>${esc(p)}</p>`).join('')}${l.supplementalSources?.length?`<p class="source">Supplemental terminology verification: ${l.supplementalSources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a>`).join(' · ')}</p>`:''}<h2>Terms to know</h2><dl>${l.definitions.map(d=>`<dt>${esc(d.term)}</dt><dd>${esc(d.definition)}</dd>`).join('')}</dl><h2>Worked example</h2><p>${esc(l.example)}</p>${diagram}<div class="notice"><strong>Common beginner mistake</strong><p>${esc(l.mistake)}</p></div><h2>Try it in your notebook</h2><p>${esc(l.exercise.question)}</p><form id="dayExercise"><label>Numerical answer<input id="dayExerciseAnswer" type="number" step="any" required value="${progress.exerciseAnswer??''}"></label><p class="source">Accepted tolerance ±${l.exercise.tolerance??.01}. All example figures are hypothetical.</p><button class="primary" type="submit">Check exercise</button></form><p id="dayExerciseResult" role="status">${progress.exerciseCorrect?'Exercise completed correctly.':''}</p><h2>Knowledge check</h2><form id="dayCheck">${l.checks.map(q=>`<fieldset><legend>${esc(q.question||q.prompt)}</legend>${q.options.map(o=>`<label class="answer-option"><input type="radio" name="${q.id}" value="${o.id}" ${progress.checkAnswers[q.id]===o.id?'checked':''} required>${esc(o.text)}</label>`).join('')}<div class="check-explanation" id="result-${q.id}" role="status"></div></fieldset>`).join('')}<button type="submit">Check all answers</button></form><h2>Write this in your notebook</h2><ul>${(Array.isArray(l.recap)?l.recap:[l.recap]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><button id="completeDay" class="primary" ${ready()?'':'disabled'}>${ctx.state.learning.dayCompleted.includes(id)?'Completion saved':'Mark lesson complete'}</button><p id="completeRequirement" class="source">Complete the exercise and answer every check correctly, then explicitly mark completion.</p><p><a class="study-link" href="#Challenges/topic/${practice}">Practice this concept</a></p><p class="source">The linked challenge is supplemental chart-guide material, attributed separately; it is not presented as a chart topic from the book.</p><nav class="lesson-navigation" aria-label="Study lesson navigation">${i?`<a href="#Guided%20Lessons/day/${dayLessons[i-1].id}">Previous: ${esc(dayLessons[i-1].title)}</a>`:''}${i<dayLessons.length-1?`<a href="#Guided%20Lessons/day/${dayLessons[i+1].id}">Next: ${esc(dayLessons[i+1].title)}</a>`:''}</nav></article></div>`;const storeProgress=()=>{ctx.state.learning.dayProgress[id]=progress;save();$('#completeDay').disabled=!ready()};$('#dayExercise').onsubmit=e=>{e.preventDefault();const answer=Number($('#dayExerciseAnswer').value);progress.exerciseCorrect=Number.isFinite(answer)&&Math.abs(answer-l.exercise.answer)<=(l.exercise.tolerance??.01)+1e-9;progress.exerciseAnswer=answer;$('#dayExerciseResult').textContent=(progress.exerciseCorrect?'Correct. ':'Try again. ')+l.exercise.explanation;storeProgress()};$('#dayCheck').onsubmit=e=>{e.preventDefault();for(const q of l.checks){const a=document.querySelector(`input[name="${q.id}"]:checked`)?.value;progress.checkAnswers[q.id]=a||'';const choice=q.options.find(o=>o.id===a);$('#result-'+q.id).innerHTML=`<p>${a===q.answer?'Correct.':'Review.'} ${esc(choice?.explanation||'Choose an answer.')}</p><details><summary>Explanation for every choice</summary><ul>${q.options.map(o=>`<li><strong>${esc(o.text)}</strong> — ${esc(o.explanation)}</li>`).join('')}</ul></details>`}storeProgress()};$('#completeDay').onclick=()=>{if(!ready())return;if(!ctx.state.learning.dayCompleted.includes(id))ctx.state.learning.dayCompleted.push(id);save();$('#completeDay').textContent='Completion saved';ctx.toast('Study lesson completion saved.')};}
function candleDiagram(d){const f={bars:[{open:d.open,high:d.high,low:d.low,close:d.close,volume:1000}],cutoff:1,timeframe:d.timeframe||'1 minute',line:null};return `<figure><figcaption>${esc(d.caption)} · Open ${d.open}, high ${d.high}, low ${d.low}, close ${d.close}</figcaption>${candles(f)}<p>Candle body: open to close. Wick: high to low. This is an original synthetic candle.</p></figure>`}
function riskDiagram(d){return `<figure><figcaption>${esc(d.caption)} · hypothetical USD/share</figcaption><svg viewBox="0 0 600 150" role="img" aria-label="Planned risk and reward: entry ${d.entry}, stop ${d.stop}, target ${d.target}"><line x1="50" x2="550" y1="75" y2="75" stroke="#b3ef7c" stroke-width="3"/><text x="30" y="45" fill="#ff9a9a">Stop $${d.stop}</text><text x="210" y="110" fill="#f0f5ee">Entry $${d.entry}</text><text x="440" y="45" fill="#b3ef7c">Target $${d.target}</text></svg><p>Planned downside: $${(d.entry-d.stop).toFixed(2)}. Potential upside: $${(d.target-d.entry).toFixed(2)}. Neither a stop fill nor a target is guaranteed.</p></figure>`}
function showPattern(id){const c=patternCards.find(c=>c.topic===id);if(!c){navigate('#Guided%20Lessons/patterns');return}$('#page').innerHTML=`<div class="training">${tabs('patterns')}<article class="card"><div class="eyebrow">Supplemental chart-guide reference</div><h1>${esc(c.title)}</h1><p>${esc(c.explanation)}</p>${chartBlock(c.chart,true)}<p class="source">${source(c.source)}</p><p>Interpretation, prices and question rules are original. Source examples do not guarantee follow-through. No historical prices were reconstructed.</p><a class="study-link" href="#Challenges/topic/${id}">Practice this concept</a></article></div>`;bindChart(c.chart,true)}
function glossaryView(){$('#page').innerHTML=`<div class="training">${tabs('glossary')}<h1>Searchable study glossary</h1><p>Original definitions for the stock day-trading track. Context matters; these are not broker account rules.</p><label>Find a term<input id="glossarySearch" type="search" placeholder="Try float, wick, risk, or VWAP"></label><div id="glossaryResults" aria-live="polite"></div></div>`;const update=()=>{const term=$('#glossarySearch').value.toLowerCase(),items=glossary.filter(g=>(g.term+' '+g.definition).toLowerCase().includes(term));$('#glossaryResults').innerHTML=`<p>${items.length} terms</p><dl>${items.map(g=>`<dt>${esc(g.term)}</dt><dd>${esc(g.definition)} <a href="#Guided%20Lessons/day/${esc(g.lessonId)}">Study in context</a></dd>`).join('')}</dl>`};$('#glossarySearch').oninput=update;update()}

